create temp table good(n text); create temp table bad(n text);
insert into good select unnest(string_to_array('Oliver Olivia Amelia Noah George Isla Arthur Ava Leo Mia Muhammad Freya Harry Lily Oscar Ivy Archie Florence Henry Sophia Theo Willow Jack Rosie Charlie Grace Freddie Ella Alfie Evie Jacob Isabella Thomas Daisy Lucas Poppy Teddy Sienna Finley Elsie Isaac Emily Tommy Matilda Edward Charlotte Ezra Sofia Hugo Evelyn Joshua Phoebe Max Ruby Albert Bonnie James Millie Elijah Alice Jaxon Harper Mohammed Aria William Luna Reuben Maya Louie Ellie Ethan Jessica Sebastian Penelope Toby Eliza Jude Emilia Dylan Margot Benjamin Hallie Rory Esme Joseph Iris Jenson Mabel Ronnie Aurora Elliot Layla Albie Violet Samuel Ada Daniel Nancy Frankie Lottie Rowan Eva Dexter Darcie Riley Zara Cassandra Cassius Jasmine Pooja Poonam Natasha Sasha Assan Hassan Basil Shahid Ashton Assad Matthias Chantal Dominic Essex Sussan Tristan Constantin Bessie Tess Jessie Massimo Raphael Sebastien Titus Dickon Cassie Analise Shakira Scunthorpe Penistone Kumar Priya Aisha Fatima Yusuf Zainab Kofi Ama Chidi Ngozi Wei Mei Hiroshi Saoirse Siobhan Niamh Callum Cormac Dara Bram Brooke Buster Abu Pippa Ebony Sexton', ' '));
insert into bad select unnest(string_to_array('Poopoo Fuuuck Shitface Bumhead Wanker Dickhead Bitchy Pissy Twatty Fuk Nazi Hitler Penis Willy Boobs Sexy Cuuunt Assface Arsehole Tits', ' '));
select 'WRONGLY BLOCKED: ' || string_agg(n, ', ') from good where not public.name_ok(n);
select 'NOT BLOCKED: ' || string_agg(n, ', ') from bad where public.name_ok(n);
select count(*) filter (where public.name_ok(n)) || '/' || count(*) || ' good names pass' from good;
